  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Tylocrebrine, a related plant alkaloid, achieved rapid brain accumulation with an AUCbrain of 2.1 µg·h/mL in mice, supporting meaningful CNS exposure for this alkaloid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Isoquinoline alkaloids such as berberine and palmatine were detected in mouse CSF after administration of HLJDD, demonstrating that this alkaloid family can cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Palmatine was detected in rat brain after oral administration, confirming brain penetration of a structurally related isoquinoline alkaloid despite its charged quaternary ammonium form.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "N-propylnorapomorphine, an aporphine alkaloid, showed good brain penetration in rat ex vivo and nonhuman primate PET studies, supporting CNS access for related benzylisoquinoline alkaloids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "SA4503, a methoxy-substituted aromatic amine radiotracer, showed high and receptor-specific brain uptake in rats, supporting that small molecules with similar physicochemical features achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Noscapine is a phthalideisoquinoline alkaloid with structural and physicochemical similarity to multiple CNS-penetrant alkaloids and radiotracers. Direct brain/CSF detection of related isoquinoline alkaloids and brain AUC data from a similar alkaloid support meaningful BBB access. No contradictory evidence was identified.",
  "evidence_gaps": [
    "No direct noscapine-specific brain/plasma or CSF measurement is present in the supplied records.",
    "Efflux transporter status (P-gp/BCRP) for noscapine was not directly assessed in the provided evidence.",
    "The brain tumor/glioma condition may alter BBB integrity, so normal-brain penetration data may not fully capture tumor-specific exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

